class FileSystem {
    private final Map<String, Integer> paths = new HashMap<>();

    public boolean createPath(String path, int value) {
        if (path == null || path.length() <= 1 || path.charAt(0) != '/') return false;
        if (paths.containsKey(path)) return false;               // already exists

        String parent = path.substring(0, path.lastIndexOf('/'));
        // parent == "" means the parent is the root, which always exists.
        if (!parent.isEmpty() && !paths.containsKey(parent)) return false;

        paths.put(path, value);
        return true;
    }

    public int get(String path) {
        return paths.getOrDefault(path, -1);
    }
}

class TrieNode {
    final Map<String, TrieNode> children = new HashMap<>();
    int value;
    boolean hasValue;
}

class FileSystem {
    private final TrieNode root = new TrieNode();

    public boolean createPath(String path, int value) {
        String[] parts = segments(path);
        if (parts == null) return false;

        TrieNode node = root;
        // Every segment but the last must already exist — the parent check.
        for (int i = 0; i < parts.length - 1; i++) {
            node = node.children.get(parts[i]);
            if (node == null) return false;
        }

        String leaf = parts[parts.length - 1];
        TrieNode existing = node.children.get(leaf);
        // A node may exist only as an ancestor; that path is still "not created".
        if (existing != null && existing.hasValue) return false;

        TrieNode target = existing != null ? existing : new TrieNode();
        target.value = value;
        target.hasValue = true;
        node.children.put(leaf, target);
        return true;
    }

    public int get(String path) {
        TrieNode node = walk(path);
        return node != null && node.hasValue ? node.value : -1;
    }

    /** Children of a directory — O(k), the reason the trie exists. */
    public List<String> ls(String path) {
        TrieNode node = "/".equals(path) ? root : walk(path);
        if (node == null) return List.of();
        List<String> names = new ArrayList<>(node.children.keySet());
        Collections.sort(names);
        return names;
    }

    /** Unlinks a whole subtree in O(depth); the descendants are collected by GC. */
    public boolean delete(String path) {
        String[] parts = segments(path);
        if (parts == null) return false;

        TrieNode node = root;
        for (int i = 0; i < parts.length - 1; i++) {
            node = node.children.get(parts[i]);
            if (node == null) return false;
        }
        return node.children.remove(parts[parts.length - 1]) != null;
    }

    private TrieNode walk(String path) {
        String[] parts = segments(path);
        if (parts == null) return null;

        TrieNode node = root;
        for (String part : parts) {
            node = node.children.get(part);
            if (node == null) return null;
        }
        return node;
    }

    /** null for any path that is not "/name(/name)*". */
    private String[] segments(String path) {
        if (path == null || path.length() < 2 || path.charAt(0) != '/') return null;
        String[] parts = path.substring(1).split("/", -1);
        for (String part : parts) {
            if (part.isEmpty()) return null;   // rejects "//a" and a trailing "/"
        }
        return parts;
    }
}

class TrieNode:
    __slots__ = ("children", "value", "has_value")

    def __init__(self):
        self.children: dict[str, "TrieNode"] = {}
        self.value = 0
        self.has_value = False


class FileSystem:
    def __init__(self):
        self.root = TrieNode()

    def createPath(self, path: str, value: int) -> bool:
        parts = self._segments(path)
        if parts is None:
            return False

        node = self.root
        for part in parts[:-1]:              # the parent must already exist
            node = node.children.get(part)
            if node is None:
                return False

        leaf = parts[-1]
        existing = node.children.get(leaf)
        if existing is not None and existing.has_value:
            return False

        target = existing or TrieNode()
        target.value, target.has_value = value, True
        node.children[leaf] = target
        return True

    def get(self, path: str) -> int:
        node = self._walk(path)
        return node.value if node and node.has_value else -1

    def _walk(self, path: str) -> TrieNode | None:
        parts = self._segments(path)
        if parts is None:
            return None
        node = self.root
        for part in parts:
            node = node.children.get(part)
            if node is None:
                return None
        return node

    @staticmethod
    def _segments(path: str) -> list[str] | None:
        if not path or len(path) < 2 or path[0] != "/":
            return None
        parts = path[1:].split("/")
        return None if any(not part for part in parts) else parts

// children is a ConcurrentHashMap<String, TrieNode>.
// putIfAbsent collapses check-then-act into one atomic step: exactly one
// caller inserts, every other caller gets the winner back and bails out.
TrieNode fresh = new TrieNode();
fresh.value = value;
fresh.hasValue = true;

TrieNode winner = node.children.putIfAbsent(leaf, fresh);
if (winner == null) return true;            // we created it

// Someone else got there first, or the node already existed as an ancestor.
synchronized (winner) {
    if (winner.hasValue) return false;
    winner.value = value;
    winner.hasValue = true;
    return true;
}

FileSystem fs = new FileSystem();

assert fs.createPath("/leetcode", 1);        // top-level: parent is the root
assert !fs.createPath("/leetcode", 2);       // duplicate rejected
assert fs.get("/leetcode") == 1;             // value unchanged by the failed create

assert !fs.createPath("/a/b", 3);            // orphan: /a does not exist
assert fs.get("/a/b") == -1;

assert fs.createPath("/leetcode/problems", 2);
assert fs.get("/leetcode/problems") == 2;
assert fs.ls("/leetcode").equals(List.of("problems"));

assert !fs.createPath("/", 1);               // root is not createable
assert !fs.createPath("", 1);                // invalid
assert !fs.createPath("/a//b", 1);           // empty segment

assert fs.createPath("/n", -5);              // negative payload is legal
assert fs.get("/n") == -5;                   // and must not read as "absent"

assert fs.delete("/leetcode");               // unlinks the subtree
assert fs.get("/leetcode/problems") == -1;
